    let max = nums.iter().max().copied().unwrap_or(0);
    let sum: i32 = nums.iter().sum();
    let avg = sum / nums.len() as i32;
    let count = nums.iter().filter(|&&n| n > avg).count();
    (max, count)
}

fn main() {
    let v = vec![1, 5, 3, 8, 2, 7];
    let (m, c) = analyze(v);
    println!("max={}, above_avg={}", m, c);
}
```

